const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const q = tok[0];
const ts = [], xs = [];
for (let i = 0; i < q; i++) { ts.push(tok[1 + 2 * i]); xs.push(tok[2 + 2 * i]); }
const set = new Set();
for (let i = 0; i < q; i++) if (ts[i] !== 3) set.add(xs[i]);
const vals = [...set].sort((a, b) => a - b);
const index = new Map();
vals.forEach((v, i) => index.set(v, i + 1));
const size = vals.length;
const tree = new Array(size + 1).fill(0);
const count = new Array(size + 1).fill(0);
let total = 0;
let top = 1;
while (top * 2 <= size) top *= 2;
const out = [];
for (let o = 0; o < q; o++) {
  const t = ts[o];
  let x = xs[o];
  if (t === 1 || t === 2) {
    let i = index.get(x);
    if (t === 2 && count[i] === 0) continue;
    const d = t === 1 ? 1 : -1;
    count[i] += d;
    total += d;
    for (; i <= size; i += i & -i) tree[i] += d;
  } else {
    if (x > total) { out.push(-1); continue; }
    let pos = 0;
    for (let step = top; step > 0; step >>= 1) {
      const nxt = pos + step;
      if (nxt <= size && tree[nxt] < x) { pos = nxt; x -= tree[nxt]; }
    }
    out.push(vals[pos]);
  }
}
console.log(out.join('\n'));

