import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken();
        int q = (int) st.nval;
        int[] t = new int[q];
        long[] x = new long[q];
        for (int i = 0; i < q; i++) {
            st.nextToken();
            t[i] = (int) st.nval;
            st.nextToken();
            x[i] = (long) st.nval;
        }
        TreeSet<Long> set = new TreeSet<>();
        for (int i = 0; i < q; i++) if (t[i] != 3) set.add(x[i]);
        long[] vals = new long[set.size()];
        int s = 0;
        for (long v : set) vals[s++] = v;
        int size = vals.length;
        int[] tree = new int[size + 1];
        int[] count = new int[size + 1];
        int total = 0;
        int top = 1;
        while (top * 2 <= size) top *= 2;
        StringBuilder sb = new StringBuilder();
        for (int o = 0; o < q; o++) {
            if (t[o] != 3) {
                int i = Arrays.binarySearch(vals, x[o]) + 1;
                if (t[o] == 2 && count[i] == 0) continue;
                int d = t[o] == 1 ? 1 : -1;
                count[i] += d;
                total += d;
                for (; i <= size; i += i & -i) tree[i] += d;
            } else {
                long k = x[o];
                if (k > total) { sb.append(-1).append('\n'); continue; }
                int pos = 0;
                for (int step = top; step > 0; step >>= 1) {
                    int nxt = pos + step;
                    if (nxt <= size && tree[nxt] < k) { pos = nxt; k -= tree[nxt]; }
                }
                sb.append(vals[pos]).append('\n');
            }
        }
        System.out.print(sb);
    }
}

