    vector<int> t(q);
    vector<long long> x(q);
    for (int i = 0; i < q; i++) scanf("%d %lld", &t[i], &x[i]);
    vector<long long> vals;
    for (int i = 0; i < q; i++) if (t[i] != 3) vals.push_back(x[i]);
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int size = vals.size();
    vector<int> tree(size + 1, 0), cnt(size + 1, 0);
    int total = 0, top = 1;
    while (top * 2 <= size) top *= 2;
    for (int o = 0; o < q; o++) {
        if (t[o] != 3) {
            int i = lower_bound(vals.begin(), vals.end(), x[o]) - vals.begin() + 1;
            if (t[o] == 2 && cnt[i] == 0) continue;
            int d = t[o] == 1 ? 1 : -1;
            cnt[i] += d;
            total += d;
            for (; i <= size; i += i & -i) tree[i] += d;
        } else {
            long long k = x[o];
            if (k > total) { printf("-1\n"); continue; }
            int pos = 0;
            for (int step = top; step > 0; step >>= 1) {
                int nxt = pos + step;
                if (nxt <= size && tree[nxt] < k) { pos = nxt; k -= tree[nxt]; }
            }
            printf("%lld\n", vals[pos]);
        }
    }
    return 0;
}
